package com.companion.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.companion.ai.growth.*; import com.companion.common.exception.BusinessException; import com.companion.common.result.ResultCode; import com.companion.dto.response.CharacterResponse; import com.companion.entity.CharacterGrowth; import com.companion.mapper.CharacterGrowthMapper; import com.companion.service.*; import lombok.RequiredArgsConstructor; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class CharacterGrowthServiceImpl implements CharacterGrowthService { private final CharacterGrowthMapper mapper; private final CharacterService characters; private final LlmGrowthEvaluator evaluator;
 @Override @Transactional public CharacterGrowth getOrCreate(Long u,Long c){validate(u,c); CharacterGrowth x=find(u,c); if(x!=null)return x; CharacterGrowth n=new CharacterGrowth(); n.setUserId(u);n.setCharacterId(c);n.setGrowthSummary("No stable growth yet.");n.setBehaviorAdaptation("Stay aligned with core identity.");n.setUserUnderstanding("No stable preference inferred yet.");n.setGrowthDirection("Observe long-term patterns gradually.");n.setVersion(0);n.setDeleted(0);n.setCreateTime(LocalDateTime.now());n.setUpdateTime(n.getCreateTime()); try{mapper.insert(n);return n;}catch(DuplicateKeyException e){return find(u,c);}}
 @Override public java.util.Optional<CharacterGrowth> get(Long u,Long c){validate(u,c);return java.util.Optional.ofNullable(find(u,c));}
 @Override public CharacterGrowth evaluateAndUpdate(Long u,Long c,GrowthEvaluationContext context){CharacterGrowth cur=getOrCreate(u,c); for(int i=0;i<2;i++){GrowthEvaluation e=evaluator.evaluate(cur,context);if(!e.changed())return cur; int v=cur.getVersion()==null?0:cur.getVersion(); CharacterGrowth n=copy(cur);n.setGrowthSummary(e.growthSummary());n.setBehaviorAdaptation(e.behaviorAdaptation());n.setUserUnderstanding(e.userUnderstanding());n.setGrowthDirection(e.growthDirection());n.setUpdateTime(LocalDateTime.now());if(mapper.updateIfVersionMatches(n,v)==1){n.setVersion(v+1);return n;}cur=getOrCreate(u,c);}return cur;}
 private CharacterGrowth copy(CharacterGrowth s){CharacterGrowth n=new CharacterGrowth();n.setId(s.getId());n.setUserId(s.getUserId());n.setCharacterId(s.getCharacterId());n.setGrowthSummary(s.getGrowthSummary());n.setBehaviorAdaptation(s.getBehaviorAdaptation());n.setUserUnderstanding(s.getUserUnderstanding());n.setGrowthDirection(s.getGrowthDirection());n.setVersion(s.getVersion());n.setDeleted(s.getDeleted());n.setCreateTime(s.getCreateTime());n.setUpdateTime(s.getUpdateTime());return n;} private CharacterGrowth find(Long u,Long c){return mapper.selectOne(new QueryWrapper<CharacterGrowth>().eq("user_id",u).eq("character_id",c));} private void validate(Long u,Long c){if(u==null||c==null)throw new BusinessException(ResultCode.PARAM_ERROR);CharacterResponse x=characters.get(u,c);if(!"AI".equals(x.getCharacterType()))throw new BusinessException(ResultCode.PARAM_ERROR.getCode(),"Growth只能绑定AI Character");}
}
